import { useState } from 'react';
import { StatusBar } from 'expo-status-bar';
import { StyleSheet, View } from 'react-native';

import HealthScreen from './screens/HealthScreen';
import HomeScreen from './screens/HomeScreen';
import TranscribeScreen from './screens/TranscribeScreen';

type Screen = 'home' | 'health' | 'transcribe';

export default function App() {
  const [screen, setScreen] = useState<Screen>('home');

  return (
    <View style={styles.container}>
      <StatusBar style="auto" />
      {screen === 'home' && (
        <HomeScreen
          onNavigateHealth={() => setScreen('health')}
          onNavigateTranscribe={() => setScreen('transcribe')}
        />
      )}
      {screen === 'health' && <HealthScreen onBack={() => setScreen('home')} />}
      {screen === 'transcribe' && <TranscribeScreen onBack={() => setScreen('home')} />}
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#fff',
  },
});

import { Pressable, StyleSheet, Text, View } from 'react-native';

type Props = {
  onBack: () => void;
};

export default function TranscribeScreen({ onBack }: Props) {
  return (
    <View style={styles.container}>
      <Pressable onPress={onBack} hitSlop={12} style={styles.backButton}>
        <Text style={styles.backText}>‹ Home</Text>
      </Pressable>

      <Text style={styles.title}>Transcribe</Text>
      <Text style={styles.status}>Speech access: not requested</Text>

      <Pressable style={styles.button}>
        <Text style={styles.buttonText}>Request Access</Text>
      </Pressable>
      <Pressable style={[styles.button, styles.buttonDisabled]} disabled>
        <Text style={[styles.buttonText, styles.buttonTextDisabled]}>Transcribe Sample</Text>
      </Pressable>

      <View style={styles.transcriptArea}>
        <Text style={styles.emptyText}>No transcript yet</Text>
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    paddingHorizontal: 24,
    paddingTop: 60,
  },
  backButton: {
    alignSelf: 'flex-start',
    marginBottom: 16,
  },
  backText: {
    fontSize: 17,
    color: '#007AFF',
  },
  title: {
    fontSize: 28,
    fontWeight: '700',
    marginBottom: 12,
  },
  status: {
    fontSize: 15,
    color: '#666',
    marginBottom: 20,
  },
  button: {
    backgroundColor: '#007AFF',
    paddingVertical: 14,
    borderRadius: 10,
    alignItems: 'center',
    marginBottom: 12,
  },
  buttonDisabled: {
    backgroundColor: '#D1D1D6',
  },
  buttonText: {
    color: '#fff',
    fontSize: 17,
    fontWeight: '600',
  },
  buttonTextDisabled: {
    color: '#8E8E93',
  },
  transcriptArea: {
    flex: 1,
    marginTop: 24,
    paddingVertical: 24,
    alignItems: 'center',
  },
  emptyText: {
    fontSize: 15,
    color: '#8E8E93',
  },
});

