import { useEffect, useState } from 'react';
import { Pressable, StyleSheet, Text, View } from 'react-native';

import ExpoHealthAccess, { DailySteps, HealthAuthorizationStatus } from '../modules/expo-health';

type Props = {
  onBack: () => void;
};

const WEEKDAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

function dayLabel(daysAgo: number): string {
  const date = new Date();
  date.setHours(0, 0, 0, 0);
  date.setDate(date.getDate() - daysAgo);
  return `${WEEKDAYS[date.getDay()]} ${MONTHS[date.getMonth()]} ${date.getDate()}`;
}

function statusLabel(status: HealthAuthorizationStatus): string {
  switch (status) {
    case 'authorized':
      return 'Health access: granted';
    case 'denied':
      return 'Health access: denied';
    default:
      return 'Health access: not requested';
  }
}

function messageFor(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

export default function HealthScreen({ onBack }: Props) {
  const [authStatus, setAuthStatus] = useState<HealthAuthorizationStatus>('notDetermined');
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [days, setDays] = useState<DailySteps[] | null>(null);
  const [requesting, setRequesting] = useState(false);
  const [logging, setLogging] = useState(false);

  const loadLast7Days = async () => {
    const result = await ExpoHealthAccess.getLast7DaysStepsAsync();
    setDays([...result].sort((a, b) => a.daysAgo - b.daysAgo));
  };

  useEffect(() => {
    let cancelled = false;

    (async () => {
      try {
        const status = await ExpoHealthAccess.getAuthorizationStatusAsync();
        if (cancelled) return;
        setAuthStatus(status);
        setErrorMessage(null);
        if (status === 'authorized') {
          await loadLast7Days();
        }
      } catch (error) {
        if (!cancelled) setErrorMessage(messageFor(error));
      }
    })();

    return () => {
      cancelled = true;
    };
  }, []);

  const handleRequestAccess = async () => {
    setRequesting(true);
    try {
      const status = await ExpoHealthAccess.requestAuthorizationAsync();
      setAuthStatus(status);
      setErrorMessage(null);
      if (status === 'authorized') {
        await loadLast7Days();
      }
    } catch (error) {
      setErrorMessage(messageFor(error));
    } finally {
      setRequesting(false);
    }
  };

  const handleLogSteps = async () => {
    setLogging(true);
    try {
      await ExpoHealthAccess.logStepsAsync(500);
      setErrorMessage(null);
      await loadLast7Days();
    } catch (error) {
      setErrorMessage(messageFor(error));
    } finally {
      setLogging(false);
    }
  };

  const canLogSteps = authStatus === 'authorized' && !logging;

  return (
    <View style={styles.container}>
      <Pressable onPress={onBack} hitSlop={12} style={styles.backButton}>
        <Text style={styles.backText}>‹ Home</Text>
      </Pressable>

      <Text style={styles.title}>Health</Text>
      <Text style={styles.status}>{errorMessage ?? statusLabel(authStatus)}</Text>

      <Pressable
        style={[styles.button, requesting && styles.buttonDisabled]}
        onPress={handleRequestAccess}
        disabled={requesting}>
        <Text style={[styles.buttonText, requesting && styles.buttonTextDisabled]}>Request Access</Text>
      </Pressable>
      <Pressable
        style={[styles.button, !canLogSteps && styles.buttonDisabled]}
        onPress={handleLogSteps}
        disabled={!canLogSteps}>
        <Text style={[styles.buttonText, !canLogSteps && styles.buttonTextDisabled]}>Log 500 Steps</Text>
      </Pressable>

      <Text style={styles.sectionHeader}>Last 7 Days</Text>

      {authStatus === 'denied' ? (
        <View style={styles.emptyState}>
          <Text style={styles.emptyText}>Health access needed</Text>
        </View>
      ) : authStatus === 'authorized' && days ? (
        <View>
          {days.map((day) => (
            <View key={day.daysAgo} style={styles.row}>
              <Text style={[styles.rowText, day.daysAgo === 0 && styles.rowTextToday]}>
                {dayLabel(day.daysAgo)} — {day.steps.toLocaleString('en-US')} steps
                {day.daysAgo === 0 ? ' (today)' : ''}
              </Text>
            </View>
          ))}
        </View>
      ) : (
        <View style={styles.emptyState}>
          <Text style={styles.emptyText}>No data yet</Text>
        </View>
      )}
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    paddingHorizontal: 24,
    paddingTop: 60,
  },
  backButton: {
    alignSelf: 'flex-start',
    marginBottom: 16,
  },
  backText: {
    fontSize: 17,
    color: '#007AFF',
  },
  title: {
    fontSize: 28,
    fontWeight: '700',
    marginBottom: 12,
  },
  status: {
    fontSize: 15,
    color: '#666',
    marginBottom: 20,
  },
  button: {
    backgroundColor: '#007AFF',
    paddingVertical: 14,
    borderRadius: 10,
    alignItems: 'center',
    marginBottom: 12,
  },
  buttonDisabled: {
    backgroundColor: '#D1D1D6',
  },
  buttonText: {
    color: '#fff',
    fontSize: 17,
    fontWeight: '600',
  },
  buttonTextDisabled: {
    color: '#8E8E93',
  },
  sectionHeader: {
    fontSize: 20,
    fontWeight: '700',
    marginTop: 24,
    marginBottom: 12,
  },
  emptyState: {
    paddingVertical: 24,
    alignItems: 'center',
  },
  emptyText: {
    fontSize: 15,
    color: '#8E8E93',
  },
  row: {
