import { useEffect, useState } from 'react';
import { Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';

import ExpoSpeech, { SpeechAuthorizationStatus } from '../modules/expo-speech';

type Props = {
  onBack: () => void;
};

type FinalResult = {
  text: string;
  seconds: number;
};

function statusLabel(status: SpeechAuthorizationStatus): string {
  switch (status) {
    case 'authorized':
      return 'Speech access: granted';
    case 'denied':
      return 'Speech access: denied';
    default:
      return 'Speech access: not requested';
  }
}

function messageFor(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

export default function TranscribeScreen({ onBack }: Props) {
  const [authStatus, setAuthStatus] = useState<SpeechAuthorizationStatus>('notDetermined');
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [requesting, setRequesting] = useState(false);
  const [transcribing, setTranscribing] = useState(false);
